        {'op': 'add', 'path': '/fields/System.Title', 'value': 'T'},
        {'op': 'add', 'path': '/fields/System.Description', 'value': '**d**'},
        mdOp,
      ]);
    });

    test('create: markdown without description adds no format op', () {
