      final plain = patched('4', _setOp('System.Description', 'x'));
      for (final f in [null, 'html', 'rtf', '']) {
        final args = {'id': 4, 'description': 'x', 'format': f};
        expect(wire(call('ado_update_description', args)), plain, reason: '$f');
      }
