      for (final f in ['html', 'xyz']) {
        final echo = call('ado_add_work_item_comment',
            {'id': 5, 'comment': 'hi', 'format': f});
        expect(echo['path'],
            '/org/proj/_apis/wit/workItems/5/comments?api-version=7.0-preview');
